/* CPython 3.14.8 embedding adapter. Real Python bytecode runs in CPython.
 * No guest file or directory capability is required by the intended fixture.
 * This contract remains pending until native + no-preopen WASI execution.
 */
#include <Python.h>
#include <stdio.h>

/* Generated by the exact pinned native CPython; defines hll_frozen[]. */
#include "hll_frozen.h"

/* Optional SDK-owned header may define HLL_REGISTER_EXTENSIONS() and declare
 * PyInit__roswasm_native. Its C sources/archives are linked into this SAME Wasm.
 * Nothing is dynamically loaded and no extension is enabled by default.
 */
#ifdef HLL_EXTENSION_HEADER
#include HLL_EXTENSION_HEADER
#endif
#ifndef HLL_REGISTER_EXTENSIONS
#define HLL_REGISTER_EXTENSIONS() 0
#endif

static int failed_status(PyStatus status, PyConfig *config)
{
    PyConfig_Clear(config);
    Py_ExitStatusException(status);
    return 1;
}

int main(int argc, char **argv)
{
    if(HLL_REGISTER_EXTENSIONS() != 0)
    {
        fputs("python extension registration failed\n", stderr);
        return 1;
    }
    PyImport_FrozenModules = hll_frozen;
    PyPreConfig pre;
    PyPreConfig_InitIsolatedConfig(&pre);
    pre.utf8_mode = 1;
    pre.configure_locale = 0;
    PyStatus status = Py_PreInitialize(&pre);
    if(PyStatus_Exception(status)) { Py_ExitStatusException(status); }
    PyConfig config;
    PyConfig_InitIsolatedConfig(&config);
    config.site_import = 0;
    config.user_site_directory = 0;
    config.use_environment = 0; /* os.environ still reflects actual WASI env. */
    config.parse_argv = 0;
    config.write_bytecode = 0;
    config.install_signal_handlers = 0;
    config.use_frozen_modules = 1;
    config.module_search_paths_set = 1;
    config.pathconfig_warnings = 0;
    config.optimization_level = 0; /* Keep fixture assertions in real bytecode. */
    config.use_hash_seed = 1;
    config.hash_seed = 0;
    status = PyConfig_SetString(&config, &config.program_name, L"uwvm-cpython314");
    if(PyStatus_Exception(status)) { return failed_status(status, &config); }
    status = PyConfig_SetString(&config, &config.home, L"/__uwvm_frozen__");
    if(PyStatus_Exception(status)) { return failed_status(status, &config); }
    status = PyConfig_SetString(&config, &config.filesystem_encoding, L"utf-8");
    if(PyStatus_Exception(status)) { return failed_status(status, &config); }
    status = PyConfig_SetString(&config, &config.stdio_encoding, L"utf-8");
    if(PyStatus_Exception(status)) { return failed_status(status, &config); }
    status = PyConfig_SetBytesArgv(&config, argc, argv);
    if(PyStatus_Exception(status)) { return failed_status(status, &config); }
    status = Py_InitializeFromConfig(&config);
    if(PyStatus_Exception(status)) { return failed_status(status, &config); }
    PyConfig_Clear(&config);
    int exit_code = 1;
    PyObject *module = PyImport_ImportModule("hll_app");
    if(module != NULL)
    {
        PyObject *result = PyObject_CallMethod(module, "main", NULL);
        Py_DECREF(module);
        if(result != NULL)
        {
            long returned = PyLong_AsLong(result);
            Py_DECREF(result);
            if(!PyErr_Occurred() && returned >= 0 && returned <= 255)
            { exit_code = (int)returned; }
            else if(!PyErr_Occurred())
            { PyErr_SetString(PyExc_ValueError, "fixture exit code out of range"); }
        }
    }
    if(PyErr_Occurred()) { PyErr_Print(); }
    if(Py_FinalizeEx() < 0) { exit_code = 120; }
    return exit_code;
}
